from typing import Dict, Any

def get_30min_mother_in_law_story(title: str = '') -> Dict[str, Any]:
    story_title = title if title else "Bữa Cơm Giỗ Đầu Sau Ba Năm Làm Dâu: Màn Lật Kèo Đòi Lại Căn Chung Cư Đứng Tên Bố Mẹ Đẻ"
    part1_full = "Mâm cỗ giỗ đầu bày biện đủ đầy tám món vừa dọn lên giữa nhà, mẹ chồng tôi đã gõ mạnh đôi đũa xuống bát sứ rồi tuyên bố trước mặt cả họ việc sang tên căn chung cư của tôi cho cô em chồng. Tôi vừa đặt bát canh măng mọc xuống giữa mâm cỗ giỗ, mồ hôi ướt đẫm cả vạt áo sau lưng, thì mẹ chồng tôi đã buông đôi đũa cái cạch xuống mâm.\n\nBà Liễu đưa mắt nhìn quanh một vòng mười mấy người họ hàng nội ngoại đang ngồi chật kín phòng khách, rồi cất giọng chép miệng đầy ngán ngẩm:\n\n\"Thời buổi này kiếm đâu ra đứa con dâu đoảng như nhà tôi chứ. Làm có năm mâm cơm cúng từ sáng tới trưa mới xong. Đã thế tiền lương bác sĩ tháng nào cũng giữ rịt lấy làm của riêng, không đóng góp cho mẹ chồng lấy một đồng tiền chợ. Đúng là con gái thời nay, sướng quen thân rồi chẳng biết thương xót nhà chồng gì cả!\"\n\nTiếng xì xào bàn tán của các bà cô, ông chú bên đằng nội lập tức rộ lên như ong vỡ tổ. Mấy người thím họ bắt đầu chép miệng nhìn tôi ái ngại, có người còn lắc đầu bảo con gái làm bác sĩ lương cao mà keo kiệt thế thì hỏng.\n\nBên cạnh tôi, Trần Quốc Hưng – người chồng đầu gối tay ấp suốt ba năm qua – ngồi im thin thít như người vô hình. Anh ta cắm mặt lướt điện thoại, tay bóc vỏ con tôm cho cô em gái ruột Trần Tuyết Mai, tuyệt nhiên không hé răng lấy một lời giải thích hay bênh vực cho người vợ vừa còng lưng nấu nướng một mình dưới bếp suốt năm tiếng đồng hồ.\n\nCô em chồng Tuyết Mai thấy mẹ mở đường thì lập tức hùa vào, giọng điệu ngọt xớt nhưng đầy gai nhọn:\n\n\"Mẹ nói đúng đấy ạ! Chị dâu lúc nào cũng tỏ vẻ bận rộn trực đêm ở bệnh viện, nhưng thực chất là trốn việc nhà. Anh trai cháu đi làm công trình vất vả nuôi cả gia đình, mua được căn chung cư cao cấp ba phòng ngủ này cho cả nhà ở, thế mà chị ấy đến cái váy hàng hiệu của cháu cũng chẳng thèm mua tặng lấy một lần!\"\n\nTôi đứng chôn chân giữa phòng khách, nhìn mâm cơm cúng tươm tất với mười hai món ăn truyền thống do chính tay mình thức dậy từ bốn giờ sáng đi chợ chọn từng con gà, mớ rau. Trong lòng tôi lúc này không còn là sự tủi thân hay uất ức như những ngày đầu mới về làm dâu nữa. Cảm giác đau đớn đã hoàn toàn biến mất, nhường chỗ cho một sự khinh bỉ lạnh ngắt và tỉnh táo đến lạ lùng.\n\nBa năm trước, khi tôi kết hôn với Quốc Hưng, anh ta chỉ là một kỹ sư giám sát công trình mới ra trường, lương tháng bấp bênh chưa đầy tám triệu đồng. Gia đình anh ta ở dưới quê nghèo khó, bố mất sớm, một mình bà Liễu gánh gồng nuôi hai anh em. Khi ấy, bố mẹ đẻ tôi vì thương con gái duy nhất đi lấy chồng phải chịu cảnh ở trọ chật chội, nên đã âm thầm bỏ ra bốn tỷ rưỡi mua đứt căn chung cư cao cấp một trăm hai mươi mét vuông này tại trung tâm thành phố. Cuốn sổ hồng mang tên bố mẹ tôi, nhưng vì giữ thể diện cho con rể, ông bà đã dặn tôi không cần công khai rùm beng, cứ để hai đứa yên tâm an cư lạc nghiệp.\n\nThế nhưng lòng tốt và sự bao dung của gia đình tôi lại vô tình nuôi dưỡng nên lòng tham vô đáy của những kẻ phông bạt.\n\nVừa dọn về ở được một tháng, bà Liễu đã gọi điện về quê khoe khắp họ hàng làng trên xóm dưới rằng con trai bà tài giỏi xuất chúng, mới hai mươi tám tuổi đã tự tay tậu chung cư tiền tỷ đón mẹ và em gái lên thành phố an dưỡng. Sau đó, bà xách làn lên ở luôn, kéo theo cả cô em chồng vừa tốt nghiệp đại học nhưng lười biếng, chỉ thích nằm lướt mạng xã hội sống ảo.\n\nSuốt ba năm qua, tiền điện nước, phí dịch vụ tòa nhà, tiền chợ búa ăn uống của cả bốn miệng ăn trong nhà này đều do một tay tôi chi trả bằng tiền lương bác sĩ và tiền thù lao làm thêm ở phòng khám tư nhân. Mỗi tháng không dưới hai mươi lăm triệu đồng! Còn tiền lương của Quốc Hưng? Anh ta bảo phải giữ lại để tích lũy làm ăn, nhưng thực chất là lén lút chuyển khoản chu cấp cho cô em gái tiêu xài hoang phí, mua sắm đồ hiệu và bao bạn trai ăn chơi.\n\nMỗi lần tôi mở lời nhắc nhở về chi tiêu, bà Liễu lại bài ca muôn thuở: \"Gia đình phải dĩ hòa vi quý, đàn bà biết kiếm tiền thì phải biết vun vén cho nhà chồng. Con Mai nó là em gái út, nó chưa có việc làm thì anh chị phải cưu mang, tính toán từng đồng với người nhà thì có ngày mất phúc!\"\n\nĐỉnh điểm là tuần trước, cô em chồng Tuyết Mai dẫn một anh chàng thiếu gia giàu có về ra mắt. Để giữ thể diện cho con gái cưng và tạo vỏ bọc môn đăng hộ đối, bà Liễu đã lén bàn với con trai một kế hoạch không tưởng: Ép tôi phải làm thủ tục sang tên căn chung cư này cho Tuyết Mai làm của hồi môn!\n\nBà ta nghĩ rằng căn nhà này là do Quốc Hưng đứng tên mua, và tôi – một đứa con dâu luôn nhẫn nhịn cam chịu – sẽ chẳng dám hé răng nửa lời vì sợ tan vỡ hôn nhân.\n\nNhìn nụ cười đắc thắng của hai mẹ con bà Liễu giữa bữa cơm giỗ, tôi từ tốn tháo chiếc tạp dề dính dầu mỡ ra, gấp gọn gàng đặt lên lưng ghế. Tôi bước tới bên cạnh chiếc bàn ăn, mỉm cười nhìn thẳng vào mắt mẹ chồng, cất giọng rõ ràng từng chữ đủ cho tất cả họ hàng hai bên cùng nghe thấy:\n\n\"Mẹ nói rất đúng ạ. Đúng là ba năm qua con chưa từng đưa cho mẹ đồng nào tiền chợ. Bởi vì nếu con đưa tiền cho mẹ, chắc cả nhà mình đã phải ăn mì gói cả tháng rồi!\"\n\nKhông khí trong phòng khách bỗng chốc im phăng phắc. Tiếng quạt trần quay vù vù cũng không át nổi sự sững sờ của mười mấy người ngồi quanh bàn. Bà Liễu trợn tròn mắt, mặt đỏ bừng lên vì tức giận:\n\n\"Mày... mày vừa nói cái gì đấy hả? Trước mặt các bác các chú đằng nội mà mày dám ăn nói hỗn láo với mẹ chồng thế à?\"\n\nQuốc Hưng lúc này mới buông điện thoại xuống, cau mày quát lớn: \"Thảo Vy! Em phát điên cái gì đấy? Mau xin lỗi mẹ ngay! Hôm nay là ngày giỗ bố anh, em đừng có làm loạn lên cho họ hàng chê cười!\"\n\nTôi không hề hoảng sợ, cũng chẳng hề cao giọng cãi vã. Tôi với tay lấy chiếc túi xách công sở của mình đặt trên kệ, rút ra một xấp tài liệu in màu dày cộp, đặt nhẹ nhàng xuống mặt bàn kính ngay trước mặt bà Liễu và các bác trưởng họ.\n\n\"Mẹ và anh Hưng đừng vội nổi nóng. Con gái làm ngành y như con trước giờ chỉ nói chuyện bằng bằng chứng khoa học và số liệu thực tế thôi. Mời các bác, các chú và mẹ cùng xem qua bản sao kê tài khoản ngân hàng ba năm qua của con!\"\n\nTôi mở trang đầu tiên của tập tài liệu, lật từng trang cho mọi người cùng thấy:\n\n\"Ba năm làm dâu, tổng số tiền chi tiêu sinh hoạt, tiền chợ búa hải sản, tiền điện nước điều hòa chạy suốt ngày đêm của mẹ và cô Mai, cùng phí dịch vụ quản lý căn hộ này... tổng cộng là tám trăm bảy mươi hai triệu đồng. Toàn bộ đều được trừ trực tiếp từ tài khoản ngân hàng mang tên Trần Thảo Vy của con! Đây là hóa đơn từng tháng có mã giao dịch đầy đủ.\"\n\nTôi quay sang nhìn thẳng vào mặt Quốc Hưng, người đang tái mét mặt mày:\n\n\"Còn anh Hưng, suốt ba năm qua anh đóng góp cho gia đình nhỏ này được bao nhiêu tiền? Để em đọc luôn cho các bác nghe nhé: Tổng cộng là không đồng! Toàn bộ tiền lương kỹ sư của anh đều được chuyển vào tài khoản của cô Mai để mua sắm túi xách, mỹ phẩm và đi du lịch sang chảnh. Các bác nhìn xem, trên người cô Mai chiếc túi xách kia trị giá ba mươi triệu, bằng đúng nửa năm tiền ăn của cả gia đình này đấy ạ!\"\n\nCô em chồng Tuyết Mai giật bắn mình, vội giấu chiếc túi xách ra sau lưng, ấp úng không thốt nên lời. Các bác đằng nội bắt đầu xúm lại xem tập sao kê ngân hàng, những tiếng xì xào chỉ trích bắt đầu quay ngược trở lại phía hai mẹ con bà Liễu.\n\nBà Liễu thẹn quá hóa giận, đập mạnh tay xuống bàn làm bát đĩa nảy lên leng keng:\n\n\"Mày... mày đem mấy cái giấy tờ này ra đây để kể công à? Đàn bà lấy chồng thì tiền của mày cũng là tiền của nhà chồng! Căn chung cư này là do con trai tao tài giỏi mua được, cho mày ở nhờ ba năm nay mày còn không biết đội ơn, dám ở đây lên mặt dạy đời ai?\"\n\nTôi nhìn bà mẹ chồng đang cố đấm ăn xôi, khóe môi khẽ nhếch lên một nụ cười mỉa mai tột cùng:\n\n\"Mẹ bảo căn chung cư này là do anh Hưng mua sao? Vậy thì con mời mẹ và cả gia đình cùng nhìn lên màn hình tivi phòng khách một chút, xem xem ai mới thực sự là chủ nhân của căn nhà này!\n\nTôi cầm chiếc điều khiển tivi bấm nút phát màn hình. Tấm ảnh chụp bản gốc cuốn sổ hồng đỏ chót cùng bản hợp đồng mua bán nhà đất mang tên bố mẹ ruột tôi hiện lên to đùng trên màn hình 65 inch! Kèm theo đó là đoạn clip ghi âm cuộc trò chuyện tối qua giữa bà Liễu và con gái âm mưu sang tên căn hộ vang lên rõ mồn một cả phòng khách!"
    part2_full = "Đoạn ghi âm cuộc bàn bạc đêm qua giữa bà Liễu và cô con gái út phát ra rõ mồn một qua loa tivi phòng khách, làm cả mười mấy người họ hàng đang cầm đũa phải khựng lại. Tiếng ghi âm từ chiếc điện thoại kết nối với dàn loa tivi vang lên rành rọt từng câu từng chữ giữa phòng khách tĩnh mịch:\n\n\"Mai này, tuần sau bạn trai con về nhà ra mắt, mẹ sẽ bảo anh Hưng làm thủ tục sang tên căn chung cư này cho con đứng tên. Con bé Vy nó hiền lành cam chịu, với lại nó sợ mang tiếng bỏ chồng nên mẹ bảo gì nó cũng phải nghe thôi. Căn nhà này đứng tên con thì bên nhà trai mới nể, sau này con lấy chồng giàu rồi thì tha hồ hưởng phúc!\"\n\nGiọng nói the thé, đầy mưu mô tính toán của chính bà Liễu phát ra từ dàn loa âm thanh vòm khiến cả gian phòng khách bốn mươi mét vuông như bị đông cứng lại trong băng giá!\n\nMười mấy người họ hàng nhà nội đang ngồi quanh mâm cỗ giỗ ai nấy đều chết trân, mắt tròn mắt dẹt nhìn nhau. Bác trưởng họ – người đàn ông cao niên uy tín nhất dòng tộc – sắc mặt lập tức tối sầm lại, đặt chén rượu xuống bàn đánh cạch một cái.\n\nBà Liễu mặt cắt không còn một giọt máu. Bà ta luống cuống nhảy dựng lên định lao tới giật chiếc điều khiển tivi trên tay tôi, nhưng tôi đã nhanh chân lùi lại một bước, ánh mắt lạnh lùng nhìn thẳng vào bộ mặt giả tạo đang run rẩy của bà ta:\n\n\"Sao thế mẹ? Đây chẳng phải là giọng nói quen thuộc của mẹ lúc tâm sự với cô con gái cưng tối hôm qua sao? Mẹ tính toán chu toàn cho con gái mình ghê nhỉ, tính cả việc cướp trắng tài sản của người khác để làm của hồi môn cho con gái đi lấy chồng giàu!\"\n\n\"Mày... mày dám lén đặt máy ghi âm trong nhà tao à? Đồ con dâu mất dạy! Mày cút ra khỏi căn nhà này ngay cho tao!\" - Bà Liễu gào lên thất thanh, cố dùng tiếng thét để che đậy đi sự xấu hổ và nhục nhã ê chề trước mặt họ hàng.\n\n\"Nhà của mẹ ư?\" - Tôi bật cười, một nụ cười thanh thản và đanh thép chưa từng có suốt ba năm qua.\n\nTôi chỉ tay lên màn hình tivi, nơi bản quét màu của cuốn Giấy chứng nhận quyền sử dụng đất và tài sản gắn liền với đất đang hiện rõ mồn một từng chi tiết:\n\n\"Bác trưởng họ và các cô chú nhìn kỹ giùm con xem: Mục người sở hữu hợp pháp đứng tên ai ạ? Đứng tên ông Trần Văn Nam và bà Nguyễn Thị Lan – tức là bố mẹ đẻ ruột của con! Toàn bộ bốn tỷ rưỡi tiền mua căn hộ này là tiền mồ hôi nước mắt của bố mẹ con gom góp cả đời trao tặng riêng cho con gái trước khi kết hôn!\"\n\nTôi quay sang nhìn Quốc Hưng, lúc này hai tay anh ta đang run lẩy bẩy, mồ hôi trán vã ra như tắm:\n\n\"Trần Quốc Hưng, ba năm qua tôi nể mặt anh là đàn ông, muốn giữ thể diện cho anh với bạn bè đồng nghiệp nên tôi mới để anh đứng ra làm việc với ban quản lý tòa nhà. Bố mẹ tôi thương anh nghèo khó, nên mới làm hợp đồng cho hai vợ chồng mượn nhà ở miễn phí để có chỗ an cư lập nghiệp. Thế nhưng anh và mẹ anh lại lấy sự tử tế của gia đình tôi làm bàn đạp để phông bạt, đi rêu rao khắp làng trên xóm dưới là anh tự tay mua nhà, rồi quay sang đối xử với tôi như một đứa ở không công!\"\n\nBác trưởng họ lúc này không nhịn nổi nữa, đập mạnh tay xuống bàn, chỉ thẳng mặt Quốc Hưng và bà Liễu:\n\n\"Thím Liễu! Thằng Hưng! Hai mẹ con thím ăn ở kiểu gì mà thất đức thế hả? Nhà của thông gia cho ở nhờ mà dám đi rêu rao là của mình, lại còn âm mưu cướp nhà của con dâu để cho con gái đi lấy chồng? Dòng họ Trần này bao đời thanh bạch gia giáo, chưa từng có loại người tham lam trơ trẽn như hai mẹ con thím! Hôm nay là ngày giỗ của chú em tôi, các người làm cái trò đồi bại này trước bàn thờ tổ tiên mà không biết ngượng à?\"\n\nMấy người thím họ ban nãy còn hùa theo chê bai tôi, giờ đây ai nấy đều cúi gằm mặt xuống ngượng ngùng. Có người vội vàng buông đũa đứng dậy xin phép ra về vì không chịu nổi bầu không khí ngột ngạt và nhục nhã này.\n\nCô em chồng Tuyết Mai thấy mọi chuyện đổ bể, bạn trai giàu có mà biết chuyện này thì coi như tan thành mây khói, liền òa lên khóc nức nở, quay sang cấu véo anh trai:\n\n\"Anh Hưng! Anh nói cái gì đi chứ! Sao anh bảo với em là căn nhà này anh đứng tên? Anh bảo chị Vy chỉ là đứa ăn bám cơ mà! Giờ thế này thì em lấy chồng kiểu gì đây hả anh ơi?\"\n\nQuốc Hưng bị dồn vào chân tường, vừa nhục nhã trước họ hàng vừa sợ mất đi người vợ có năng lực kinh tế, liền quay ngoắt sang nắm lấy tay tôi, giọng run rẩy van nài:\n\n\"Vy ơi... anh xin em! Chuyện trong nhà đóng cửa bảo nhau, em làm ầm lên trước mặt họ hàng thế này thì mặt mũi anh để đi đâu nữa? Mẹ già rồi nên lẩm cẩm, con Mai nó còn trẻ người non dạ chưa hiểu chuyện. Anh biết em vất vả, từ nay anh hứa sẽ đưa hết lương cho em giữ, em bỏ qua cho mẹ con anh lần này được không em?\"\n\nTôi lạnh lùng hất tay anh ta ra, ánh mắt dứt khoát không một chút do dự:\n\n\"Mặt mũi của anh quan trọng, vậy ba năm qua thể diện và lòng tự trọng của tôi bị mẹ và em gái anh giẫm đạp dưới chân thì để ở đâu? Khi mẹ anh bêu rếu tôi keo kiệt trước mặt họ hàng, anh ở đâu? Khi em gái anh chê tôi là đứa ở dơ bẩn, anh đã làm gì? Anh chỉ biết cắm mặt ăn tôm rồi dặn tôi phải biết nhẫn nhịn vì gia đình!\"\n\nTôi mở chiếc túi xách, rút ra hai tờ văn bản đã được công chứng viên ký sẵn vào sáng nay:\n\n\"Đây là Thông báo chấm dứt việc cho mượn nhà do bố mẹ tôi ký tên với tư cách chủ sở hữu hợp pháp. Đúng mười hai giờ trưa mai, tôi sẽ đổi toàn bộ mật mã khóa cửa vân tay của căn hộ này. Tôi cho gia đình anh đúng hai mươi tư tiếng đồng hồ để thu dọn toàn bộ đồ đạc cá nhân và rời khỏi căn nhà này! Quá thời hạn, ban quản lý tòa nhà và lực lượng bảo vệ sẽ tiến hành niêm phong xử lý theo đúng quy định pháp luật!\"\n\nBà Liễu nghe thấy bị đuổi khỏi căn chung cư cao cấp, mất đi chốn ở sang chảnh và cuộc sống an nhàn bấy lâu nay thì phát điên lên. Bà ta lao tới như một kẻ mất trí, giơ móng tay sắc nhọn định cào vào mặt tôi:\n\n\"Con ranh mất dạy! Mày dám đuổi tao à? Tao là mẹ chồng mày! Tao đã sống ở đây ba năm thì đây là nhà của tao! Tao không đi đâu hết, để xem đứa nào dám đuổi tao ra khỏi cái nhà này!\n\nBà Liễu vừa giơ tay định lao vào tôi thì cửa chính căn hộ bỗng mở toang! Hai nhân viên an ninh tòa nhà cùng một vị luật sư trong bộ vest lịch lãm bước vào, trên tay cầm biên bản vi phạm trật tự công cộng và văn bản ủy quyền cưỡng chế tài sản của chủ sở hữu hợp pháp! Vị luật sư cất giọng dõng dạc: 'Bà Trương Thị Liễu, hành vi đe dọa xâm phạm thân thể và chiếm giữ bất động sản trái phép của bà đã được camera ghi lại toàn bộ!'"
    part3_full = "Luật sư Nguyễn Hoàng Minh mở cặp da lấy ra bản di chúc công chứng và giấy chứng nhận quyền sở hữu gốc do bố mẹ đẻ tôi ủy quyền, đặt ngay ngắn lên mặt bàn kính. Vị luật sư đại diện theo ủy quyền của bố mẹ tôi – Luật sư Nguyễn Hoàng Minh – bước thẳng vào phòng khách, phong thái đĩnh đạc và uy nghiêm khiến cơn điên loạn của bà Liễu lập tức bị chặn đứng giữa chừng.\n\nHai nhân viên an ninh to lớn đứng chắn ngay trước mặt tôi, tách bà mẹ chồng ra một khoảng cách an toàn. Trưởng ban an ninh tòa nhà nghiêm giọng nói qua bộ đàm:\n\n\"Bà Trương Thị Liễu và ông Trần Quốc Hưng! Chúng tôi nhận được yêu cầu hỗ trợ khẩn cấp từ chủ sở hữu hợp pháp của căn hộ 1804 này. Theo nội quy khu đô thị và hợp đồng quản lý vận hành, việc gây rối trật tự công cộng, to tiếng cãi vã làm ảnh hưởng đến cư dân xung quanh và có hành vi bạo lực sẽ bị xử lý nghiêm khắc. Yêu cầu bà bình tĩnh ngồi xuống, nếu tiếp tục có hành vi quá khích, chúng tôi buộc phải mời công an phường sở tại vào lập biên bản xử phạt hành chính ngay lập tức!\"\n\nLời cảnh cáo dứt khoát của nhân viên an ninh như một gáo nước lạnh buốt dội thẳng vào đầu bà Liễu. Bà ta đứng sững sờ, hai tay buông thõng, nhìn quanh phòng khách lúc này chỉ còn lại sự im lặng đến rợn người.\n\nBác trưởng họ và các cô chú đằng nội đã lần lượt lắc đầu ngán ngẩm, lục tục kéo nhau ra cửa về hết từ lúc nào. Không một ai trong dòng họ thèm nán lại để nói đỡ cho mẹ con bà lấy một lời. Trước sự thật rành rành về giấy tờ pháp lý và đoạn ghi âm trơ trẽn kia, bất kỳ ai có chút liêm sỉ cũng cảm thấy nhục nhã thay cho gia đình họ Trần.\n\nLuật sư Minh mở chiếc cặp tài liệu da, rút ra bản hợp đồng ủy quyền và thông báo thu hồi bất động sản có công chứng, đặt thẳng thắn lên mặt bàn trước mặt Quốc Hưng:\n\n\"Ông Trần Quốc Hưng, tôi xin thông báo rõ ràng về mặt pháp lý: Căn hộ này thuộc quyền sở hữu riêng hợp pháp của ông Trần Văn Nam và bà Nguyễn Thị Lan. Bảy năm qua, việc ông và gia đình cư trú tại đây hoàn toàn dựa trên sự đồng thuận cho mượn nhà tạm thời của chủ sở hữu. Hiện tại, chủ nhà đã chính thức đơn phương chấm dứt quyền cho mượn nhà này do bên mượn có hành vi vi phạm nghiêm trọng về ứng xử đạo đức và có dấu hiệu chiếm đoạt tài sản.\"\n\nLuật sư Minh nhìn đồng hồ đeo tay rồi tiếp tục bằng chất giọng đanh thép:\n\n\"Thời hạn bàn giao lại mặt bằng là trước mười hai giờ trưa ngày mai. Đúng thời điểm đó, ban quản lý sẽ hỗ trợ chủ sở hữu reset lại toàn bộ hệ thống khóa cửa thông minh và hủy mã thẻ thang máy của các thành viên không có tên trên sổ đỏ. Mọi đồ đạc cá nhân của gia đình ông sau thời gian trên nếu không tự di dời sẽ được lập biên bản niêm phong và chuyển xuống kho bãi của tòa nhà với chi phí do bên ông tự chịu trách nhiệm.\"\n\nTừng câu từng chữ của vị luật sư như những chiếc đinh đóng chặt vào cỗ quan tài chôn vùi toàn bộ sĩ diện và sự ngạo mạn của gia đình nhà chồng.\n\nBà Liễu lúc này mới thực sự nhận ra mình không còn đường lui. Sự giả tạo, đanh đá thường ngày bỗng chốc sụp đổ hoàn toàn. Bà ta ngã quỵ xuống chiếc ghế sofa da cao cấp, ôm mặt khóc lóc thảm thiết, giọng khàn đặc đầy cay đắng:\n\n\"Trời ơi là trời... sao số tôi khổ thế này! Già rồi còn bị con dâu đuổi ra đường... Hưng ơi, con làm gì đi chứ, chẳng lẽ con để mẹ và em gái con phải ra gầm cầu ở à con ơi? Nhà này ba năm nay mẹ lau từng viên gạch, quét từng góc nhà, sao người ta lại nỡ cạn tình cạn nghĩa thế này...\"\n\nTôi nhìn người đàn bà đang cố đóng vai nạn nhân ấy, trong lòng không hề có lấy một chút thương hại hay dao động. Suốt ba năm làm dâu, tôi đã nhìn quá rõ bộ mặt thật sau những giọt nước mắt cá sấu này rồi.\n\n\"Mẹ đừng khóc lóc kể khổ nữa ạ,\" - Tôi cất giọng điềm tĩnh, ngắt lời bà ta: \"Ba năm qua người phải lau dọn căn nhà này từ tầng trên xuống tầng dưới là con, chứ mẹ và cô Mai chỉ biết nằm điều hòa xem phim rồi gọi đồ ăn về vứt rác đầy nhà. Mẹ bảo mẹ bị đuổi ra gầm cầu sao? Dưới quê mẹ vẫn còn căn nhà cấp bốn ba gian rộng rãi của bố để lại cơ mà? Chẳng qua ở quê không có máy lạnh, không có trung tâm thương mại sang chảnh để cô Mai đi check-in sống ảo, nên mẹ mới không chịu về thôi!\"\n\nTôi quay sang nhìn Quốc Hưng, lúc này anh ta đang quỳ sụp một bên gối dưới sàn nhà, hai mắt đỏ hoe vì ân hận và xấu hổ:\n\n\"Còn anh Hưng, đây là tờ đơn ly hôn tôi đã ký sẵn. Tôi không cần anh phải chia chác bất kỳ tài sản nào, bởi vì trên thực tế tài sản của anh chỉ là con số không tròn trĩnh. Tôi chỉ yêu cầu anh ký vào đơn để giải thoát cho cả hai.\"\n\nQuốc Hưng run rẩy ngẩng đầu lên, hai giọt nước mắt muộn màng lăn dài trên đôi má hốc hác:\n\n\"Vy... anh xin em, đừng ly hôn mà em! Anh sai rồi, thực sự anh sai rồi! Ba năm qua anh nhu nhược, anh ngu ngốc để mẹ và em gái làm tổn thương em. Anh hứa từ mai anh sẽ thuê một căn nhà trọ nhỏ cho mẹ và em Mai ra ở riêng, hai vợ chồng mình dọn đi nơi khác sống độc lập, anh sẽ làm lại từ đầu để bù đắp cho em mà Vy!\"\n\nTôi khẽ lắc đầu, nụ cười trên môi đượm vẻ xót xa cho chính tuổi thanh xuân ba năm của mình:\n\n\"Muộn rồi anh Hưng ạ. Tình cảm và sự tôn trọng của con người ta giống như một chiếc bát sứ, một khi đã làm rơi vỡ tan tành thì dù anh có dùng keo hàn gắn lại thế nào, những vết nứt xấu xí vẫn mãi mãi ở đó. Ba năm qua tôi đã cho anh hàng trăm cơ hội để đứng lên bảo vệ người vợ của mình, nhưng mỗi lần đứng giữa đúng và sai, anh đều chọn cách im lặng để làm tròn chữ hiếu mù quáng. Chiếc bát vỡ này, tôi không cần nữa!\"\n\nNói xong, tôi không buồn nhìn lại ba con người đang chìm trong sự hoang mang và tuyệt vọng tột cùng ấy nữa. Tôi xách chiếc túi xách cá nhân của mình, bước từng bước thanh thản ra phía cửa chính.\n\nTrước khi bước vào thang máy, tôi quay lại nhìn căn nhà lần cuối, khẽ nói với vị luật sư: \"Ngày mai phiền anh Minh và ban quản lý giám sát việc chuyển đồ giúp tôi. Sau khi họ dọn đi xong, hãy thuê dịch vụ khử khuẩn và dọn dẹp lại toàn bộ căn hộ. Tôi sẽ nhờ bố mẹ làm thủ tục cho một gia đình tử tế thuê lại.\"\n\nBước ra khỏi sảnh tòa nhà chung cư, một cơn gió mùa thu mát rượi thổi qua làn tóc tôi. Bầu trời sau cơn mưa bỗng trở nên trong xanh và khoáng đạt lạ kỳ. Ba năm chịu đựng, nhẫn nhịn và hy sinh vì một cuộc hôn nhân sai lầm cuối cùng đã chính thức khép lại.\n\nTôi hít một hơi thật sâu, cảm nhận lồng ngực mình nhẹ nhõm như vừa trút bỏ được một tảng đá nghìn cân. Phụ nữ chúng ta sinh ra không phải để làm chiếc thảm lau chân cho sự ích kỷ và vô ơn của người khác. Khi chúng ta có tri thức, có sự độc lập tài chính và lòng tự trọng, thì không có bất kỳ ai có quyền chà đạp hay làm tổn thương chúng ta được nữa! Cuộc đời tự do và rực rỡ của tôi... bây giờ mới thực sự bắt đầu!\n\nBạn nghĩ gì về sự thức tỉnh của người phụ nữ tự chủ? Hãy để lại bình luận bên dưới nhé!"
